const crypto = require('crypto');
const item = $input.first();
const secret = $env.ORDER_INTAKE_HMAC_SECRET || '';
const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body || {});
const headers = item.json.headers || {};
const provided = String(headers['x-signature'] || '').replace(/^sha256=/, '').trim();
const expected = crypto.createHmac('sha256', secret).update(raw).digest('hex');
let authOk = false;
try {
  authOk = provided.length === expected.length &&
    crypto.timingSafeEqual(Buffer.from(provided, 'hex'), Buffer.from(expected, 'hex'));
} catch (e) { authOk = false; }
return [{ json: { authOk, body: item.json.body || {} } }];

// Normalise the ticket once, so every downstream node — both provider
// chains, both parsers, the human queue and the dead-letter row — is
// looking at the same fields rather than re-deriving them.
const body = $json.body || {};
const ticketId = String(body.ticket_id || body.id || '').trim();
const subject = String(body.subject || '').trim();
const text = String(body.body || body.message || '').trim();
const errors = [];
if (!ticketId) errors.push('ticket_id is required');
if (!subject && !text) errors.push('the ticket needs a subject or a body');
return [{ json: {
  ticket_id: ticketId,
  subject,
  body: text,
  valid_input: errors.length === 0,
  input_errors: errors,
  prompt: 'Triage this support ticket.\n\nSubject: ' + subject + '\n\nBody: ' + text,
} }];

const PROVIDER = 'primary';

