// DETERMINISTIC PARSER. No model is involved in deciding whether a model's
// answer is usable — that decision is made here, by code, every time, the same
// way. An "auto-fixing" parser that asks another model to repair the first
// model's output turns one non-deterministic step into two.
// -------------------------------------------------------------------------

const SCHEMA = {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://example.invalid/schemas/triage-output.schema.json",
    "title": "triage-output",
    "description": "The ONLY shape the support-triage workflow will act on. A model response is not trusted because it parsed — it is trusted because it conforms to this. Kept as a file so the contract is reviewable and diffable on its own; the workflow's parser embeds a copy, and a test asserts the two never drift.",
    "type": "object",
    "additionalProperties": false,
    "required": [
      "category",
      "urgency",
      "summary",
      "requires_human"
    ],
    "properties": {
      "category": {
        "type": "string",
        "description": "Routing destination. A closed set: an unknown category cannot be routed, so it must fail validation rather than be forwarded to a queue that does not exist.",
        "enum": [
          "billing",
          "technical",
          "account",
          "other"
        ]
      },
      "urgency": {
        "type": "string",
        "description": "Closed set. A model that returns 7 or \"very high\" here must be rejected, not coerced — coercion is how a critical ticket silently becomes a normal one.",
        "enum": [
          "low",
          "normal",
          "high",
          "critical"
        ]
      },
      "summary": {
        "type": "string",
        "description": "One-line summary shown to a human. Bounded so a runaway response cannot be written into a UI field verbatim.",
        "minLength": 1,
        "maxLength": 280
      },
      "requires_human": {
        "type": "boolean",
        "description": "Strictly boolean. \"probably\" is not a decision an automated router can act on."
      }
    }
  };

// Strip the wrapping a chat model puts around JSON. Handles a fenced block, and
// prose on either side of one, because those are what models actually return —
// not because the prompt asked for them.
function extractJson(text) {
  let t = String(text === null || text === undefined ? '' : text).trim();
  const fenced = t.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenced) t = fenced[1].trim();
  const first = t.indexOf('{');
  const last = t.lastIndexOf('}');
  if (first !== -1 && last > first) t = t.slice(first, last + 1);
  return t.trim();
}

// A small, explicit validator for exactly the subset of JSON Schema this
// contract uses. Explicit beats a dependency here: the rules a response is held
// to are readable in the same file that applies them.
function validate(value, schema, path) {
  const where = path ? path + ': ' : '';
  const errors = [];

  if (schema.type === 'object') {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
      return [where + 'expected an object'];
    }
    for (const key of schema.required || []) {
      if (!(key in value)) errors.push(where + 'missing required field "' + key + '"');
    }
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) {
        if (!(key in (schema.properties || {}))) {
          errors.push(where + 'unexpected field "' + key + '"');
        }
      }
    }
    for (const key of Object.keys(schema.properties || {})) {
      if (key in value) {
        errors.push(...validate(value[key], schema.properties[key], path ? path + '.' + key : key));
      }
    }
    return errors;
  }

  if (schema.type === 'string') {
    if (typeof value !== 'string') return [where + 'expected a string, got ' + typeof value];
    if (schema.enum && schema.enum.indexOf(value) === -1) {
      errors.push(where + 'must be one of [' + schema.enum.join(', ') + '], got "' + value + '"');
    }
    if (schema.minLength !== undefined && value.length < schema.minLength) {
      errors.push(where + 'must be at least ' + schema.minLength + ' character(s)');
    }
    if (schema.maxLength !== undefined && value.length > schema.maxLength) {
      errors.push(where + 'must be at most ' + schema.maxLength + ' characters');
    }
    return errors;
  }

  if (schema.type === 'boolean') {
    if (typeof value !== 'boolean') return [where + 'expected a boolean, got ' + typeof value];
    return errors;
  }

  return errors;
}

const ticket = $('Build Ticket').first().json;
const j = $input.first().json || {};
// The agent answers on `output`, the chain on `text`.
const raw = j.output !== undefined ? j.output : (j.text !== undefined ? j.text : '');

let triage = null;
let errors = [];
const candidate = extractJson(raw);

if (!candidate) {
  errors = ['the model returned an empty response'];
} else {
  try {
    triage = JSON.parse(candidate);
  } catch (e) {
    errors = ['response is not valid JSON: ' + e.message];
  }
  if (triage !== null) errors = validate(triage, SCHEMA, '');
}

return [{ json: {
  ticket_id: ticket.ticket_id,
  provider: PROVIDER,
  valid: errors.length === 0,
  errors,
  triage,
  raw: String(raw).slice(0, 2000),
} }];

