// Both ways of failing arrive here: the fallback returned something
// unusable, or the fallback provider was unreachable. Normalising them
// into one shape means the human queue, the dead-letter row and the
// response cannot disagree about what happened.
const t = $('Build Ticket').first().json;
const primary = $('Parse Triage').first().json;
const j = $input.first().json || {};
// A parsed result carries `valid`; an error item does not.
const providerFailed = j.valid === undefined;
const fallbackErrors = providerFailed
  ? ['fallback provider unavailable: ' + String((j.error && j.error.message) || 'unknown error')]
  : (j.errors || []);
return [{ json: {
  ticket_id: t.ticket_id,
  reason: (providerFailed
    ? 'the fallback provider was unavailable'
    : 'no provider returned a usable triage') + ': ' + fallbackErrors.join('; '),
  raw: providerFailed ? '' : String(j.raw || ''),
  primary_errors: primary.errors || [],
  fallback_errors: fallbackErrors,
  subject: t.subject,
  body: t.body,
} }];
